-- Guarded Cheese Hunt v1.  Legacy quest tables remain historical only.
CREATE TABLE tbl_owner_cheese_hunt_missions (
 mission_id INTEGER PRIMARY KEY AUTOINCREMENT, description TEXT NOT NULL, reward_amount INTEGER NOT NULL CHECK(reward_amount>0), required_clicks INTEGER NOT NULL CHECK(required_clicks BETWEEN 1 AND 100), movement_pattern TEXT NOT NULL CHECK(movement_pattern IN ('random','edge_hunter','sneaky','corner_lurker','scatter_zone','fair_shuffle')), movement_speed TEXT NOT NULL CHECK(movement_speed IN ('slow','normal','fast')), hidden_areas INTEGER NOT NULL CHECK(hidden_areas IN (0,1)), winner_message TEXT NOT NULL, role_id TEXT, expires_at TEXT, status TEXT NOT NULL CHECK(status IN ('draft','active','inactive')) DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, activated_at TEXT
);
CREATE UNIQUE INDEX owner_cheese_hunt_one_active ON tbl_owner_cheese_hunt_missions(status) WHERE status='active';
CREATE TABLE tbl_owner_cheese_hunt_progress (mission_id INTEGER NOT NULL REFERENCES tbl_owner_cheese_hunt_missions(mission_id), player_id TEXT NOT NULL, click_count INTEGER NOT NULL DEFAULT 0 CHECK(click_count>=0), last_capture_at INTEGER, completed_at TEXT, PRIMARY KEY(mission_id,player_id));
CREATE TABLE tbl_owner_cheese_hunt_claims (claim_id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id INTEGER NOT NULL REFERENCES tbl_owner_cheese_hunt_missions(mission_id), player_id TEXT NOT NULL, reward_amount INTEGER NOT NULL, role_id TEXT, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')), version INTEGER NOT NULL DEFAULT 1, reviewed_by TEXT, review_reason TEXT, reviewed_at TEXT, credited_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(mission_id,player_id));
CREATE TABLE tbl_owner_cheese_hunt_audit (audit_id INTEGER PRIMARY KEY AUTOINCREMENT, actor_subject TEXT NOT NULL, event_type TEXT NOT NULL, mission_id INTEGER, claim_id INTEGER, request_hash TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tbl_owner_cheese_hunt_receipts (actor_subject TEXT NOT NULL, operation TEXT NOT NULL, idempotency_key_hash TEXT NOT NULL, request_hash TEXT NOT NULL, audit_id INTEGER NOT NULL REFERENCES tbl_owner_cheese_hunt_audit(audit_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(actor_subject,operation,idempotency_key_hash));
CREATE TABLE tbl_owner_cheese_hunt_role_delivery (claim_id INTEGER PRIMARY KEY REFERENCES tbl_owner_cheese_hunt_claims(claim_id), role_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','delivered','failed')) DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER owner_cheese_hunt_audit_immutable_update BEFORE UPDATE ON tbl_owner_cheese_hunt_audit BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TRIGGER owner_cheese_hunt_audit_immutable_delete BEFORE DELETE ON tbl_owner_cheese_hunt_audit BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TRIGGER owner_cheese_hunt_receipt_immutable_update BEFORE UPDATE ON tbl_owner_cheese_hunt_receipts BEGIN SELECT RAISE(ABORT,'immutable receipt'); END;
CREATE TRIGGER owner_cheese_hunt_receipt_immutable_delete BEFORE DELETE ON tbl_owner_cheese_hunt_receipts BEGIN SELECT RAISE(ABORT,'immutable receipt'); END;
